<?php require __DIR__.'/../middleware.php';api_method('GET');$slug=trim($_GET['slug']??'');if($slug==='')api_json(['ok'=>false,'error'=>'slug is required'],400);$q=db()->prepare("SELECT title,slug,location,employment_type,summary,description,closing_date,published_at FROM jobs WHERE slug=? AND status='published' AND (closing_date IS NULL OR closing_date>=CURDATE()) LIMIT 1");$q->execute([$slug]);$job=$q->fetch();if(!$job)api_json(['ok'=>false,'error'=>'Job not found'],404);api_json(['ok'=>true,'data'=>$job]);